CREATE TABLE t6(m DEFAULT 10,n DEFAULT 5,PRIMARY KEY(m,n)); CREATE TABLE t7(x INTEGER PRIMARY KEY); CREATE TABLE t8(o COLLATE nocase DEFAULT 'abc'); CREATE TABLE t9(p NOT NULL,q DOUBLE CHECK(q!=0),r STRING UNIQUE); CREATE TABLE x1 AS SELECT * FROM t6; CREATE TABLE x2 AS SELECT * FROM t7; CREATE TABLE x3 AS SELECT * FROM t8; CREATE TABLE x4 AS SELECT * FROM t9;